 steps:[S('Model threats and attack fixtures','Name asset, attacker action, affected route and expected invariant for each attack.',['Use a disposable app and synthetic credentials.','A successful GET health check is not evidence of authorization.'],'Every fixture predicts both an HTTP outcome and a persisted-state outcome.'),S('Harden lifecycle under pressure','Rehearse simultaneous login, expiry and revocation with an injected clock.',['The one-session constraint needs transactional replacement.','A role change requires re-evaluating privileges on future requests.'],'Exactly one newly issued token remains usable after simultaneous logins.'),S('Inspect browser and error defenses','Run hostile forms/text, inspect policy headers and search logs for secret markers.',['CSP must match the actual page resources.','Keep no-store on private pages without forcing public pages to reveal session data.'],'An injected payload remains literal and a copied revoked cookie cannot mutate anything.')],
 cases:[['Fixation','chosen cookie before successful login','fresh unrelated token; chosen token rejected'],['Concurrent login','two valid logins at once','only one active server session afterward'],['Idle expiry','31 minutes inactivity','401; server rejects token'],['Forged CSRF','session cookie with attacker form','403; no write'],['XSS/SQL input','hostile text and SQL-like string','literal text; data and schema intact'],['Private response','GET account page','no-store and reviewed browser headers; no secrets']],
